void far win_YardClosed(int a, int b, int render)
{
    struct { int far *p; } h;

    h.p = &yardAnimHandle;
    if (*h.p) {
        clip_Push();
        clip_SetWin(0x1900);
        hanim_RemoveAllAnimObjects(*h.p);
        if (render)
            hanim_RenderAnimSet(*h.p, 0x1900, mapTileRect.x,
                                mapTileRect.y, a, b, 0x200, 0xe2);
        hanim_RemoveAnimSet(*h.p);
        clip_Pop();
        *h.p = 0;
    }
}
